import test from 'node:test';import assert from 'node:assert/strict';
import {STARTER_TITLE,STARTER_BPM,STARTER_SCENES,buildStarterArrangement,installStarterPatterns} from './starter-song.js';
const pattern=()=>Array.from({length:64},()=>({note:0,on:false,accent:false,slide:false,gate:.5,velocity:.8,probability:1,ratchets:1}));
const mod=()=>({state:{root:36,steps:16,pattern:0,patterns:Array.from({length:8},pattern),p:{},params:{},polyArp:{}}});
const kit=()=>({bank:{patterns:Array.from({length:16},()=>({length:16,steps:Array.from({length:11},pattern)}))},voices:Array.from({length:11},()=>({level:.8})),tempo:126});
function fixture(){return {drum:kit(),mono:mod(),poly:mod(),texture:mod(),acid:mod()}}
const channels=Object.fromEntries(['drums','acid','poly','texture','tb303','sample','external'].map(id=>[id,{mute:false,solo:false,sc:false,v:{level:.8,cut:1}}]));
const base={drumPattern:0,bassPattern:0,polyPattern:0,texturePattern:0,acidPattern:0,channels,polyArp:{enabled:true,key:0},harmony:{key:0},masterFX:{time:.4},sidechain:{amount:.8}};
test('starter song has intentional contrast and coherent harmonic roots',()=>{const d=buildStarterArrangement(base);assert.equal(STARTER_BPM,122);assert.equal(STARTER_TITLE,'BLUE HOUR');assert.equal(d.auto,true);assert.equal(d.scenes.length,8);assert.equal(d.lanes.filter(l=>l.enabled).length,0);for(let i=0;i<8;i++){const x=d.scenes[i].data;assert.equal(x.monoRoot%12,[9,9,5,0,5,9,7,9][i]);assert.equal(x.polyArp.key,9);assert.equal(x.harmony.scale,'MINOR');assert.ok(['drums','acid','poly','texture','tb303'].filter(c=>!x.channels[c].mute).length<=3);assert.equal(x.channels.sample.mute,true);assert.equal(x.channels.external.mute,true)}});
test('bass and acid never clash in any scene',()=>{for(const x of buildStarterArrangement(base).scenes){assert.ok(x.data.channels.acid.mute||x.data.channels.tb303.mute,x.name)}});
test('only rhythmic and diatonic notes enabled',()=>{let m=fixture();installStarterPatterns(m);assert.equal(m.drum.tempo,122);assert.equal(m.poly.state.polyArp.scale,'MINOR');for(let i=0;i<8;i++){let sc=STARTER_SCENES[i];const a=m.mono.state.patterns[i].slice(0,16).filter(s=>s.on);const b=m.acid.state.patterns[i].slice(0,16).filter(s=>s.on);assert.ok(a.length<=7&&b.length<=7);assert.ok(m.texture.state.patterns[i].filter(s=>s.on).length===1);for(const row of [a,b])for(const s of row)assert.ok([0,3,4,5,7].includes(s.note),sc.name+' '+s.note)}});
test('drum break removes kick and drop brings it back',()=>{let m=fixture();installStarterPatterns(m);assert.equal(m.drum.bank.patterns[4].steps[0].filter(s=>s.on).length,0);assert.equal(m.drum.bank.patterns[5].steps[0].filter(s=>s.on).length,4)});
test('scenes have distinct bar lengths and remain editable independent copies',()=>{const d=buildStarterArrangement(base);d.scenes[1].data.channels.drums.mute=true;assert.equal(d.scenes[2].data.channels.drums.mute,false);assert.equal(base.channels.drums.mute,false)});
